{
  "status": "ok",
  "rules": [
    {
      "field": "drip_tray",
      "property": "visible",
      "condition": {
        "op": "not",
        "args": [
          {
            "op": "all",
            "args": [
              {
                "op": "ne",
                "field": "glazing_area",
                "value": true
              },
              {
                "op": "ne",
                "field": "item",
                "value": "wheel"
              }
            ]
          }
        ]
      },
      "quote": "Unless neither the glazing area is used nor the item is wheel, show drip tray status; in that excluded case, hide it."
    },
    {
      "field": "drip_tray",
      "property": "required",
      "condition": {
        "op": "all",
        "args": [
          {
            "op": "eq",
            "field": "glazing_area",
            "value": true
          },
          {
            "op": "eq",
            "field": "returned_clean",
            "value": false
          }
        ]
      },
      "quote": "While that field is shown, require it exactly when the glazing area is used."
    },
    {
      "field": "porter_note",
      "property": "visible",
      "condition": {
        "op": "gte",
        "field": "cart_count",
        "value": 2
      },
      "quote": "Hide porter note recorded for fewer than 2 carts; show it for 2 or 3 carts."
    },
    {
      "field": "porter_note",
      "property": "required",
      "condition": {
        "op": "all",
        "args": [
          {
            "op": "eq",
            "field": "item",
            "value": "wheel"
          },
          {
            "op": "eq",
            "field": "cart_count",
            "value": 3
          }
        ]
      },
      "quote": "While porter note recorded is shown, require an answer exactly when the item is wheel and there are 3 carts."
    }
  ]
}
